/* Generated bytes and independent guards; no GPU or VM. */
#include <assert.h>
#include <stdlib.h>
#include <string.h>
#include "mvo-metal-swizzle.h"
int main(void)
{
    const uint32_t large[] = {255,256,257,3455,3456,3457,3839,3840,3841};
    for (uint32_t test=0;test<139;test++) {
        uint32_t width=test<130?test:large[test-130];
        for (unsigned misalignment=0;misalignment<32;misalignment++) {
            size_t prefix=32+misalignment, bytes=(size_t)width*4;
            unsigned char *allocation=malloc(prefix+bytes+64);
            assert(allocation);
            memset(allocation,0xa7,prefix+bytes+64);
            unsigned char *pixels=allocation+prefix;
            for(size_t b=0;b<bytes;b++) pixels[b]=(unsigned char)((b*29+test*7+misalignment*17)%251);
            mvo_rgba_to_bgra_row(pixels,width);
            for(size_t b=0;b<bytes;b++) {
                size_t original=(b&~(size_t)3)+(b%4==0?2:b%4==2?0:b%4);
                assert(pixels[b]==(unsigned char)((original*29+test*7+misalignment*17)%251));
            }
            for(size_t b=0;b<prefix;b++) assert(allocation[b]==0xa7);
            for(size_t b=0;b<64;b++) assert(pixels[bytes+b]==0xa7);
            mvo_rgba_to_bgra_row(pixels,width);
            for(size_t b=0;b<bytes;b++) assert(pixels[b]==(unsigned char)((b*29+test*7+misalignment*17)%251));
            free(allocation);
        }
    }
    return 0;
}
